-- ============================================
-- LUMA — Thème 1 (Restaurant) : LONG x4 — Un repas de fiançailles
-- ============================================


update scenarios set content = '{"characters": {"partner": "ton/ta partenaire", "waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "This restaurant is beautiful, I can''t believe you planned all this.", "text_fr": "Ce restaurant est magnifique, je n''arrive pas à croire que tu aies tout organisé.", "choices": [{"text": "I wanted tonight to be really special.", "text_fr": "Je voulais que ce soir soit vraiment spécial.", "next": "n2"}, {"text": "I have something important to ask you tonight.", "text_fr": "J''ai quelque chose d''important à te demander ce soir.", "next": "n2b"}, {"text": "(stay mysterious and just smile)", "text_fr": "(reste mystérieux et souris juste)", "next": "n2c"}]}, "n2": {"speaker": "waiter", "text": "Good evening, would you like to start with some champagne?", "text_fr": "Bonsoir, vous souhaitez commencer par du champagne ?", "choices": [{"text": "Yes, please, we''re celebrating something special.", "text_fr": "Oui, s''il vous plaît, on célèbre quelque chose de spécial.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "You''re making me nervous, in a good way!", "text_fr": "Tu me rends nerveux/nerveuse, mais dans le bon sens !", "choices": [{"text": "Just wait until dessert.", "text_fr": "Attends juste le dessert.", "next": "n3"}, {"text": "Don''t worry, it''s a good kind of important.", "text_fr": "T''inquiète, c''est le bon genre d''important.", "next": "n3"}]}, "n2c": {"speaker": "partner", "text": "That smile is telling me something''s up... a good something?", "text_fr": "Ce sourire me dit qu''il se passe quelque chose... quelque chose de bien ?", "choices": [{"text": "You''ll just have to wait and see.", "text_fr": "Tu vas devoir attendre et voir.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Wonderful, I''ll bring a bottle right away.", "text_fr": "Merveilleux, j''apporte une bouteille tout de suite.", "choices": [{"text": "Thank you so much.", "text_fr": "Merci beaucoup.", "next": "n4"}]}, "n4": {"speaker": "partner", "text": "Okay, now I''m really curious what you''re planning. Talk to me!", "text_fr": "Bon, maintenant je suis vraiment curieux/curieuse de savoir ce que tu prépares. Dis-moi tout !", "choices": [{"text": "Let''s just enjoy dinner first, I promise it''s worth the wait.", "text_fr": "Profitons d''abord du dîner, je promets que ça vaut l''attente.", "next": "n5"}, {"text": "(nervously drop your fork, feeling the pressure of the moment)", "text_fr": "(fais tomber ta fourchette nerveusement, sentant la pression du moment)", "next": "n5b"}]}, "n5": {"speaker": "waiter", "text": "Here are your appetizers — the chef''s specialty tonight.", "text_fr": "Voici vos entrées — la spécialité du chef ce soir.", "choices": [{"text": "This looks incredible, thank you.", "text_fr": "Ça a l''air incroyable, merci.", "next": "n6"}]}, "n5b": {"speaker": "partner", "text": "Are you okay? You seem really nervous tonight.", "text_fr": "Ça va ? Tu sembles vraiment nerveux/nerveuse ce soir.", "choices": [{"text": "I am, actually — there''s something big I want to ask you.", "text_fr": "Je le suis, en fait — il y a quelque chose d''important que je veux te demander.", "next": "n6"}, {"text": "Just a little, but it''s nothing bad, I promise.", "text_fr": "Juste un peu, mais c''est rien de mauvais, promis.", "next": "n6"}]}, "n6": {"speaker": "partner", "text": "(Halfway through dinner) This has honestly been a perfect evening already.", "text_fr": "(À mi-chemin du dîner) Ça a honnêtement déjà été une soirée parfaite.", "choices": [{"text": "It''s about to get even better, I think.", "text_fr": "Ça va devenir encore mieux, je pense.", "next": "n7"}, {"text": "I''m so glad you''re enjoying it.", "text_fr": "Je suis tellement content(e) que tu apprécies.", "next": "n7"}]}, "n7": {"speaker": "waiter", "text": "(Approaching with the ring, hidden inside a small dessert box, discreetly.)", "text_fr": "(S''approchant avec la bague, cachée dans une petite boîte à dessert, discrètement.)", "choices": [{"text": "(Take the box from the waiter, heart racing.)", "text_fr": "(Prends la boîte des mains du serveur, le cœur battant.)", "next": "n8"}, {"text": "(Signal the waiter to wait just a moment longer.)", "text_fr": "(Fais signe au serveur d''attendre juste un instant de plus.)", "next": "n7b"}]}, "n7b": {"speaker": "partner", "text": "What was that about? You seem even more nervous now!", "text_fr": "C''était quoi ça ? Tu sembles encore plus nerveux/nerveuse maintenant !", "choices": [{"text": "(Take a deep breath) Okay, I can''t wait any longer.", "text_fr": "(Prends une grande respiration) OK, je ne peux plus attendre.", "next": "n8"}]}, "n8": {"speaker": "waiter", "text": "(Places a small box on the table, then steps back respectfully.)", "text_fr": "(Pose une petite boîte sur la table, puis recule respectueusement.)", "choices": [{"text": "(Open the box slowly, revealing the ring.)", "text_fr": "(Ouvre la boîte lentement, révélant la bague.)", "next": "n9"}]}, "n9": {"speaker": "partner", "text": "(Gasps, hand over mouth) Is that... what I think it is?", "text_fr": "(Sursaute, main sur la bouche) C''est... ce que je crois ?", "choices": [{"text": "(Get down on one knee) Will you marry me?", "text_fr": "(Mets-toi à genoux) Veux-tu m''épouser ?", "next": "n10"}, {"text": "I''ve been planning this for months. Will you marry me?", "text_fr": "Je prépare ça depuis des mois. Veux-tu m''épouser ?", "next": "n10"}]}, "n10": {"speaker": "partner", "text": "(Stunned silence, then tears) Yes! Yes, of course!", "text_fr": "(Silence stupéfait, puis des larmes) Oui ! Oui, bien sûr !", "choices": [{"text": "You''ve just made me the happiest person alive.", "text_fr": "Tu viens de faire de moi la personne la plus heureuse au monde.", "next": "n11"}, {"text": "I''ve been waiting so long for the right moment to ask.", "text_fr": "J''attendais depuis si longtemps le bon moment pour demander.", "next": "n11b"}]}, "n11": {"speaker": "waiter", "text": "(The whole restaurant starts to notice and quietly applaud.)", "text_fr": "(Tout le restaurant commence à remarquer et applaudit discrètement.)", "choices": [{"text": "(Laugh, a bit embarrassed but overjoyed) Everyone''s looking!", "text_fr": "(Ris, un peu gêné(e) mais ravi(e)) Tout le monde regarde !", "next": "n12"}]}, "n11b": {"speaker": "partner", "text": "You didn''t have to wait, you know — I would have said yes anytime.", "text_fr": "Tu n''avais pas besoin d''attendre, tu sais — j''aurais dit oui n''importe quand.", "choices": [{"text": "I wanted it to be perfect, and I think it was.", "text_fr": "Je voulais que ce soit parfait, et je crois que ça l''était.", "next": "n12"}]}, "n12": {"speaker": "waiter", "text": "Congratulations to you both! The champagne is on us tonight.", "text_fr": "Félicitations à vous deux ! Le champagne est offert ce soir.", "choices": [{"text": "Thank you so much, this means the world to us.", "text_fr": "Merci beaucoup, ça compte énormément pour nous.", "next": "n13"}, {"text": "That''s incredibly kind, thank you!", "text_fr": "C''est incroyablement gentil, merci !", "next": "n13"}]}, "n13": {"speaker": "partner", "text": "I want to remember every single detail of tonight forever.", "text_fr": "Je veux me souvenir de chaque détail de ce soir pour toujours.", "choices": [{"text": "Me too. This is just the beginning.", "text_fr": "Moi aussi. Ce n''est que le début.", "next": "end_yes"}, {"text": "Let''s take a photo to remember this moment.", "text_fr": "Prenons une photo pour se souvenir de ce moment.", "next": "end_photo"}]}, "end_yes": {"speaker": "waiter", "text": "What a beautiful moment to witness — congratulations again!", "text_fr": "Quel beau moment d''assister à ça — encore félicitations !", "end": true, "ending_label": "Elle/il a dit oui ! Soirée parfaite 💍"}, "end_photo": {"speaker": "waiter", "text": "Of course — let me take that photo for you both, on the house.", "text_fr": "Bien sûr — laissez-moi prendre cette photo pour vous deux, offerte par la maison.", "end": true, "ending_label": "Un souvenir capturé pour toujours 📸💍"}}}'::jsonb, is_playable = true
where title = 'Un repas de fiançailles'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
